INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI001', 'HDSAT-RW-M16-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Kelp forests are underwater areas with a high density of kelp, which covers a large part of the world''s coastlines. Smaller areas of anchored kelp are called kelp beds. They are recognized as one of the most productive and dynamic ecosystems on Earth. Although algal kelp forest combined with coral reefs only cover 0.1% of Earth''s total surface, they account for 0.9% of global primary productivity. Kelp forests occur worldwide throughout temperate and polar coastal oceans. In 2007, kelp forests were also discovered in tropical waters near Ecuador.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Kelp beds cover a larger area than kelp forests and support more marine species."}, {"id": "B", "text": "Kelp forests are exceptionally productive coastal ecosystems that grow in a wide range of ocean waters."}, {"id": "C", "text": "Kelp forests are restricted to the temperate and polar coastal oceans."}, {"id": "D", "text": "Coral reefs account for a larger share of global primary productivity than kelp forests do."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Kelp forest", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Kelp_forest', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI001', 'B', ARRAY['B']::TEXT[], 'The text presents kelp forests as highly productive, notes that they cover very little of Earth''s surface yet contribute disproportionately to primary productivity, and describes a range that extends from polar to tropical waters. The other choices reverse a detail or invent a comparison.', '{"A": "The text defines kelp beds as the smaller areas of anchored kelp, not the larger ones.", "C": "The final sentence reports kelp forests discovered in tropical waters near Ecuador, so the range is wider than the choice allows.", "D": "The text gives a combined figure for kelp forests and coral reefs and never compares the two."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF001', 'HDSAT-RW-M16-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Kelp forests are underwater areas with a high density of kelp, which covers a large part of the world''s coastlines. Smaller areas of anchored kelp are called kelp beds. They are recognized as one of the most productive and dynamic ecosystems on Earth. Although algal kelp forest combined with coral reefs only cover 0.1% of Earth''s total surface, they account for 0.9% of global primary productivity. Kelp forests occur worldwide throughout temperate and polar coastal oceans. In 2007, kelp forests were also discovered in tropical waters near Ecuador.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "expand only when ocean temperatures are falling."}, {"id": "B", "text": "grow in waters with very different temperature conditions."}, {"id": "C", "text": "survive only where coral reefs are also present."}, {"id": "D", "text": "thrive best in the warm waters near Ecuador."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Kelp forest", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Kelp_forest', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF001', 'B', ARRAY['B']::TEXT[], 'The passage places kelp forests in temperate, polar and, since 2007, tropical waters. A range spanning such different climates supports the inference that the forests tolerate a broad range of temperatures.', '{"C": "The text never ties kelp forests to the presence of coral reefs.", "D": "The Ecuador discovery shows kelp forests can grow in tropical water; it does not show that they do best there.", "A": "Nothing in the text links kelp expansion to falling temperatures."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS001', 'HDSAT-RW-M16-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Kelp forests are underwater areas with a high density of kelp, which covers a large part of the world''s coastlines. Smaller areas of anchored kelp are called kelp beds. They are recognized as one of the most productive and dynamic ecosystems on Earth. Although algal kelp forest combined with coral reefs only cover 0.1% of Earth''s total surface, they account for 0.9% of global primary productivity. Kelp forests occur worldwide throughout temperate and polar coastal oceans. In 2007, kelp forests were also discovered in tropical waters near Ecuador.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines kelp forests, stresses their productivity relative to their area, and describes where they grow."}, {"id": "B", "text": "It traces the history of kelp research from its beginnings to the present."}, {"id": "C", "text": "It presents a problem caused by kelp beds and then proposes a solution."}, {"id": "D", "text": "It compares two competing explanations for the decline of kelp forests."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Kelp forest", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Kelp_forest', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS001', 'A', ARRAY['A']::TEXT[], 'The text opens with a definition, turns to the contrast between the small area kelp forests cover and their large contribution to productivity, and closes with their geographic range.', '{"B": "The text does not describe the history of research on kelp.", "D": "No decline is mentioned, and no competing explanations are offered.", "C": "Kelp beds are defined, not presented as a problem, and no solution is proposed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE001', 'HDSAT-RW-M16-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Kelp forests are underwater areas with a high density of kelp, which covers a large part of the world''s coastlines. Smaller areas of anchored kelp are called kelp beds. They are recognized as one of the most productive and dynamic ecosystems on Earth. Although algal kelp forest combined with coral reefs only cover 0.1% of Earth''s total surface, they account for 0.9% of global primary productivity. Kelp forests occur worldwide throughout temperate and polar coastal oceans. In 2007, kelp forests were also discovered in tropical waters near Ecuador.', 'Which quotation from the text most directly supports the claim that kelp forests contribute far more to global productivity than their share of Earth''s surface would suggest?', '[{"id": "A", "text": "Although algal kelp forest combined with coral reefs only cover 0.1% of Earth''s total surface, they account for 0.9% of global primary productivity."}, {"id": "B", "text": "They are recognized as one of the most productive and dynamic ecosystems on Earth."}, {"id": "C", "text": "Smaller areas of anchored kelp are called kelp beds."}, {"id": "D", "text": "Kelp forests occur worldwide throughout temperate and polar coastal oceans."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Kelp forest", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Kelp_forest', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE001', 'A', ARRAY['A']::TEXT[], 'Only the sentence pairing 0.1% of Earth''s surface with 0.9% of global primary productivity supplies the comparison the claim depends on.', '{"B": "This sentence asserts high productivity but gives no measure of area, so it cannot show a disproportion.", "D": "This sentence describes geographic range, not productivity.", "C": "This sentence defines a term and says nothing about productivity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI002', 'HDSAT-RW-M16-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Roman concrete, also called opus caementicium, was used in construction in ancient Rome. Like its modern equivalent, Roman concrete was based on a hydraulic-setting cement added to an aggregate. Many buildings and structures still standing today, such as bridges, reservoirs and aqueducts, were built with this material, which attests to both its versatility and its durability. It was previously thought that its strength was enhanced by the incorporation of pozzolanic ash where available (particularly in the Bay of Naples). The addition of ash prevented cracks from spreading. However, research in 2023 has shown that the incorporation of mixtures of different types of lime, forming conglomerate "clasts" allowed the concrete to self-repair cracks, which was more likely the case.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Pozzolanic ash has been confirmed as the only reason Roman structures are still standing."}, {"id": "B", "text": "The durability of Roman concrete is now attributed to lime clasts that let the material repair its own cracks."}, {"id": "C", "text": "Roman concrete was less durable than modern concrete because it contained no aggregate."}, {"id": "D", "text": "Roman builders added lime clasts to concrete in order to decorate interior surfaces."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman concrete", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_concrete', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI002', 'B', ARRAY['B']::TEXT[], 'The passage sets up the earlier ash explanation and then presents 2023 research showing that lime clasts allowed the concrete to self-repair cracks.', '{"C": "The text compares Roman concrete to its modern equivalent but never calls it less durable, and it says the material contained aggregate.", "A": "The ash explanation is described as the earlier view, which 2023 research revised.", "D": "Interior decoration is mentioned separately, through stucco, frescoes and marble, not as the purpose of lime clasts."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF002', 'HDSAT-RW-M16-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Roman concrete, also called opus caementicium, was used in construction in ancient Rome. Like its modern equivalent, Roman concrete was based on a hydraulic-setting cement added to an aggregate. Many buildings and structures still standing today, such as bridges, reservoirs and aqueducts, were built with this material, which attests to both its versatility and its durability. It was previously thought that its strength was enhanced by the incorporation of pozzolanic ash where available (particularly in the Bay of Naples). The addition of ash prevented cracks from spreading. However, research in 2023 has shown that the incorporation of mixtures of different types of lime, forming conglomerate "clasts" allowed the concrete to self-repair cracks, which was more likely the case.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the absence of aggregate in the Roman mixture."}, {"id": "B", "text": "stucco and marble applied to interior surfaces."}, {"id": "C", "text": "pozzolanic ash imported from the Bay of Naples."}, {"id": "D", "text": "lime clasts that could seal cracks as they formed."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman concrete", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_concrete', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF002', 'D', ARRAY['D']::TEXT[], 'The 2023 finding is that lime clasts allowed self-repair. Completing the sentence with lime clasts follows directly from that finding; the other completions either contradict the text or name unrelated details.', '{"C": "The ash explanation is the older view that the 2023 research displaced.", "A": "The text says Roman concrete was based on cement added to an aggregate, so the mixture was not aggregate-free.", "B": "Stucco and marble are described as interior decoration, not as a cause of crack resistance."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS002', 'HDSAT-RW-M16-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Roman concrete, also called opus caementicium, was used in construction in ancient Rome. Like its modern equivalent, Roman concrete was based on a hydraulic-setting cement added to an aggregate. Many buildings and structures still standing today, such as bridges, reservoirs and aqueducts, were built with this material, which attests to both its versatility and its durability. It was previously thought that its strength was enhanced by the incorporation of pozzolanic ash where available (particularly in the Bay of Naples). The addition of ash prevented cracks from spreading. However, research in 2023 has shown that the incorporation of mixtures of different types of lime, forming conglomerate "clasts" allowed the concrete to self-repair cracks, which was more likely the case.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a material''s durability, contrasts an earlier explanation with newer research, and notes when the material came into use."}, {"id": "B", "text": "It argues that ancient engineering was superior by comparing Roman bridges with modern reservoirs."}, {"id": "C", "text": "It traces the decline of Roman concrete after the end of the Roman Empire."}, {"id": "D", "text": "It explains how to mix Roman concrete and urges modern builders to copy the method."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman concrete", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_concrete', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS002', 'A', ARRAY['A']::TEXT[], 'The text establishes durability, presents the older ash explanation, revises it with 2023 research, and adds the date from which the material was widely used.', '{"D": "The text offers no mixing instructions and no recommendation to builders.", "B": "It mentions modern concrete only for comparison and never ranks the two.", "C": "The decline of Roman concrete is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE002', 'HDSAT-RW-M16-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Roman concrete, also called opus caementicium, was used in construction in ancient Rome. Like its modern equivalent, Roman concrete was based on a hydraulic-setting cement added to an aggregate. Many buildings and structures still standing today, such as bridges, reservoirs and aqueducts, were built with this material, which attests to both its versatility and its durability. It was previously thought that its strength was enhanced by the incorporation of pozzolanic ash where available (particularly in the Bay of Naples). The addition of ash prevented cracks from spreading. However, research in 2023 has shown that the incorporation of mixtures of different types of lime, forming conglomerate "clasts" allowed the concrete to self-repair cracks, which was more likely the case.', 'Which quotation from the text most directly supports the claim that Roman concrete could repair cracks without human intervention?', '[{"id": "A", "text": "Roman concrete was in widespread use from about 150 BC"}, {"id": "B", "text": "allowed the concrete to self-repair cracks"}, {"id": "C", "text": "Many buildings and structures still standing today, such as bridges, reservoirs and aqueducts, were built with this material"}, {"id": "D", "text": "The addition of ash prevented cracks from spreading."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman concrete", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_concrete', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE002', 'B', ARRAY['B']::TEXT[], 'The phrase naming self-repair is the only quotation that describes the concrete healing cracks on its own; the others concern durability, the earlier explanation, or dating.', '{"C": "Long-standing buildings show durability but not the ability to repair damage.", "D": "Preventing cracks from spreading describes the older ash explanation, not self-repair.", "A": "The date of widespread use says nothing about how the material responds to cracks."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI003', 'HDSAT-RW-M16-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Waggle dance is a term used in beekeeping and ethology for a particular figure-eight dance of the honey bee. By performing this dance, successful foragers can share information about the direction and distance to patches of flowers yielding nectar and pollen, to water sources, or to new nest-site locations with other members of the colony. The waggle dance and the round dance are two forms of dance behaviour that are part of a continuous transition. As the distance between the resource and the hive increases, the round dance transforms into variations of a transitional dance, which, when communicating resources at even greater distances, becomes the waggle dance. In the case of Apis mellifera ligustica, the round dance is performed until the resource is about ten metres (33 ft) away from the hive, transitional dances are performed when the resource is at a distance of twenty to thirty metres (66 to 98 ft) away from the hive, and finally, when it is located at distances greater than forty metres (130 ft) from the hive, the waggle dance is performed.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Round dances communicate direction, while waggle dances communicate only distance."}, {"id": "B", "text": "The waggle dance is performed only for resources more than forty metres from the hive."}, {"id": "C", "text": "Karl von Frisch was the first person to observe honeybees dancing."}, {"id": "D", "text": "Honeybees share the direction and distance of resources through dances whose form changes as the resource gets farther away."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Waggle dance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Waggle_dance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI003', 'D', ARRAY['D']::TEXT[], 'The passage defines the dance, says it conveys direction and distance, and then describes how the dance shifts from round to transitional to waggle as distance increases.', '{"B": "The forty-metre figure describes when the full waggle dance appears in one subspecies, not the only circumstance in which it is used.", "A": "The text says the dance shares both direction and distance, and it presents the two dances as points on a continuum.", "C": "Von Frisch is not mentioned in this part of the article, and the text does not claim he was the first observer."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF003', 'HDSAT-RW-M16-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Waggle dance is a term used in beekeeping and ethology for a particular figure-eight dance of the honey bee. By performing this dance, successful foragers can share information about the direction and distance to patches of flowers yielding nectar and pollen, to water sources, or to new nest-site locations with other members of the colony. The waggle dance and the round dance are two forms of dance behaviour that are part of a continuous transition. As the distance between the resource and the hive increases, the round dance transforms into variations of a transitional dance, which, when communicating resources at even greater distances, becomes the waggle dance. In the case of Apis mellifera ligustica, the round dance is performed until the resource is about ten metres (33 ft) away from the hive, transitional dances are performed when the resource is at a distance of twenty to thirty metres (66 to 98 ft) away from the hive, and finally, when it is located at distances greater than forty metres (130 ft) from the hive, the waggle dance is performed.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "perform the full waggle dance because the resource is beyond forty metres."}, {"id": "B", "text": "perform a transitional dance rather than either the round dance or the full waggle dance."}, {"id": "C", "text": "abandon dancing and lead the colony directly to the resource."}, {"id": "D", "text": "perform the round dance until the resource is ten metres away."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Waggle dance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Waggle_dance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF003', 'B', ARRAY['B']::TEXT[], 'In Apis mellifera ligustica the transitional dances occur at twenty to thirty metres, so a forager returning from twenty-five metres would perform a transitional dance.', '{"D": "Ten metres marks the upper end of the round dance, not a resource twenty-five metres away.", "A": "Forty metres is the threshold for the full waggle dance; twenty-five metres falls below it.", "C": "The text describes dancing as the means of sharing information and never mentions leading by flight."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS003', 'HDSAT-RW-M16-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Waggle dance is a term used in beekeeping and ethology for a particular figure-eight dance of the honey bee. By performing this dance, successful foragers can share information about the direction and distance to patches of flowers yielding nectar and pollen, to water sources, or to new nest-site locations with other members of the colony. The waggle dance and the round dance are two forms of dance behaviour that are part of a continuous transition. As the distance between the resource and the hive increases, the round dance transforms into variations of a transitional dance, which, when communicating resources at even greater distances, becomes the waggle dance. In the case of Apis mellifera ligustica, the round dance is performed until the resource is about ten metres (33 ft) away from the hive, transitional dances are performed when the resource is at a distance of twenty to thirty metres (66 to 98 ft) away from the hive, and finally, when it is located at distances greater than forty metres (130 ft) from the hive, the waggle dance is performed.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that the term round dance should replace the term waggle dance."}, {"id": "B", "text": "It compares two theories about bee navigation and concludes that neither is supported."}, {"id": "C", "text": "It describes the life cycle of a honeybee colony from founding to decline."}, {"id": "D", "text": "It defines a behavior, explains what the behavior communicates, and traces how its form changes with distance."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Waggle dance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Waggle_dance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS003', 'D', ARRAY['D']::TEXT[], 'The text moves from definition to function to the distance-dependent progression from round dance to waggle dance.', '{"B": "No competing theories are presented, and no conclusion about their support is drawn.", "C": "The colony''s life cycle is not described.", "A": "The text notes a suggestion about terminology but does not argue for replacing one term with the other."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE003', 'HDSAT-RW-M16-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'Waggle dance is a term used in beekeeping and ethology for a particular figure-eight dance of the honey bee. By performing this dance, successful foragers can share information about the direction and distance to patches of flowers yielding nectar and pollen, to water sources, or to new nest-site locations with other members of the colony. The waggle dance and the round dance are two forms of dance behaviour that are part of a continuous transition. As the distance between the resource and the hive increases, the round dance transforms into variations of a transitional dance, which, when communicating resources at even greater distances, becomes the waggle dance. In the case of Apis mellifera ligustica, the round dance is performed until the resource is about ten metres (33 ft) away from the hive, transitional dances are performed when the resource is at a distance of twenty to thirty metres (66 to 98 ft) away from the hive, and finally, when it is located at distances greater than forty metres (130 ft) from the hive, the waggle dance is performed.', 'Which quotation from the text most directly supports the claim that the type of dance a honeybee performs depends on how far away a resource is?', '[{"id": "A", "text": "The waggle dance and the round dance are two forms of dance behaviour that are part of a continuous transition."}, {"id": "B", "text": "By performing this dance, successful foragers can share information about the direction and distance to patches of flowers yielding nectar and pollen"}, {"id": "C", "text": "the round dance is performed until the resource is about ten metres (33 ft) away from the hive, transitional dances are performed when the resource is at a distance of twenty to thirty metres (66 to 98 ft) away from the hive, and finally, when it is located at distances greater than forty metres (130 ft) from the hive, the waggle dance is performed"}, {"id": "D", "text": "Waggle dance is a term used in beekeeping and ethology for a particular figure-eight dance of the honey bee."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Waggle dance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Waggle_dance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE003', 'C', ARRAY['C']::TEXT[], 'The quotation assigns a different dance to each distance band, which is exactly the dependence the claim describes.', '{"B": "This sentence says distance is communicated but does not link the form of the dance to distance.", "A": "This sentence calls the dances a continuum without giving the distances involved.", "D": "This sentence defines the term and gives the shape of the dance."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI004', 'HDSAT-RW-M16-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A printing press is a machine that applies pressure to transfer ink onto a surface made of paper, cloth, or a similar material. Its workers are known as printing press operators. It marked a significant improvement on earlier methods, in which the paper was rubbed by hand to transfer applied ink to the printing surface. The printing press was invented by the German goldsmith Johannes Gutenberg around 1440, and its subsequent global spread revolutionized literary production and communication during the early modern period. The spread of printing brought about an era of mass communication in European society, allowing information to quickly spread across Europe and contributing to the Reformation and the Scientific Revolution. The cost of printed texts declined and their availability increased, facilitating higher adult literacy rates across Europe. Books increasingly appeared in vernacular languages rather than Latin, and national languages were standardized.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Printed texts became more expensive but more widely available after 1440."}, {"id": "B", "text": "The Reformation and the Scientific Revolution slowed the spread of printing."}, {"id": "C", "text": "The printing press was invented in order to standardize European national languages."}, {"id": "D", "text": "The printing press spread quickly and reshaped communication, literacy, and language in early modern Europe."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Printing press", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Printing_press', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI004', 'D', ARRAY['D']::TEXT[], 'The passage describes the invention, the rapid spread of printing, and several consequences: mass communication, cheaper and more available texts, higher literacy, and the rise of vernacular and standardized national languages.', '{"C": "Language standardization is described as a consequence of printing, not its purpose.", "A": "The text says the cost of printed texts declined while availability increased.", "B": "The text says printing contributed to those movements, not that they slowed printing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF004', 'HDSAT-RW-M16-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A printing press is a machine that applies pressure to transfer ink onto a surface made of paper, cloth, or a similar material. Its workers are known as printing press operators. It marked a significant improvement on earlier methods, in which the paper was rubbed by hand to transfer applied ink to the printing surface. The printing press was invented by the German goldsmith Johannes Gutenberg around 1440, and its subsequent global spread revolutionized literary production and communication during the early modern period. The spread of printing brought about an era of mass communication in European society, allowing information to quickly spread across Europe and contributing to the Reformation and the Scientific Revolution. The cost of printed texts declined and their availability increased, facilitating higher adult literacy rates across Europe. Books increasingly appeared in vernacular languages rather than Latin, and national languages were standardized.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the invention of the wooden handpress."}, {"id": "B", "text": "a rise in the price of printed texts."}, {"id": "C", "text": "the decline of Latin as the dominant language of European books."}, {"id": "D", "text": "the disappearance of national languages."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Printing press", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Printing_press', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF004', 'C', ARRAY['C']::TEXT[], 'The text states that books increasingly appeared in vernacular languages rather than Latin, which supports the inference that Latin''s dominance in printed books declined.', '{"A": "The handpress is the machine itself, not a consequence of vernacular printing.", "B": "The text reports that the cost of printed texts declined.", "D": "The text says national languages were standardized, not that they disappeared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS004', 'HDSAT-RW-M16-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A printing press is a machine that applies pressure to transfer ink onto a surface made of paper, cloth, or a similar material. Its workers are known as printing press operators. It marked a significant improvement on earlier methods, in which the paper was rubbed by hand to transfer applied ink to the printing surface. The printing press was invented by the German goldsmith Johannes Gutenberg around 1440, and its subsequent global spread revolutionized literary production and communication during the early modern period. The spread of printing brought about an era of mass communication in European society, allowing information to quickly spread across Europe and contributing to the Reformation and the Scientific Revolution. The cost of printed texts declined and their availability increased, facilitating higher adult literacy rates across Europe. Books increasingly appeared in vernacular languages rather than Latin, and national languages were standardized.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines a machine, describes its invention and spread, and lists several consequences of that spread."}, {"id": "B", "text": "It explains the mechanics of the handpress in detail and gives instructions for operating one."}, {"id": "C", "text": "It compares manuscript copying with printing and concludes that copying was more accurate."}, {"id": "D", "text": "It traces the decline of printing after the Scientific Revolution."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Printing press", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Printing_press', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS004', 'A', ARRAY['A']::TEXT[], 'The opening defines the press, the middle describes Gutenberg''s invention and its spread, and the final sentences list effects on communication, literacy and language.', '{"C": "The text mentions hand rubbing only to contrast it with the press and makes no claim about accuracy.", "B": "The text gives no mechanical detail or operating instructions.", "D": "The text presents printing as contributing to the Scientific Revolution, not declining after it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE004', 'HDSAT-RW-M16-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A printing press is a machine that applies pressure to transfer ink onto a surface made of paper, cloth, or a similar material. Its workers are known as printing press operators. It marked a significant improvement on earlier methods, in which the paper was rubbed by hand to transfer applied ink to the printing surface. The printing press was invented by the German goldsmith Johannes Gutenberg around 1440, and its subsequent global spread revolutionized literary production and communication during the early modern period. The spread of printing brought about an era of mass communication in European society, allowing information to quickly spread across Europe and contributing to the Reformation and the Scientific Revolution. The cost of printed texts declined and their availability increased, facilitating higher adult literacy rates across Europe. Books increasingly appeared in vernacular languages rather than Latin, and national languages were standardized.', 'Which quotation from the text most directly supports the claim that printing changed which languages Europeans read, not only how many books they could obtain?', '[{"id": "A", "text": "The basic design of the wooden handpress was largely consistent for over three centuries"}, {"id": "B", "text": "Books increasingly appeared in vernacular languages rather than Latin, and national languages were standardized."}, {"id": "C", "text": "The printing press was invented by the German goldsmith Johannes Gutenberg around 1440"}, {"id": "D", "text": "The cost of printed texts declined and their availability increased, facilitating higher adult literacy rates across Europe."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Printing press", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Printing_press', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE004', 'B', ARRAY['B']::TEXT[], 'Only the quotation about vernacular languages and standardization addresses a change in the languages of printed books.', '{"D": "This sentence is about cost, availability and literacy, not about which languages were read.", "C": "This sentence dates and credits the invention.", "A": "This sentence describes the durability of the press design."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI005', 'HDSAT-RW-M16-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Waste heat from energy use is the main cause of the urban heat island effect."}, {"id": "B", "text": "Urban areas tend to be warmer than surrounding rural areas, mainly because their land surfaces have been modified."}, {"id": "C", "text": "Urban areas occupy about half of Earth''s land surface."}, {"id": "D", "text": "The temperature difference between city and countryside is largest during the day."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI005', 'B', ARRAY['B']::TEXT[], 'The passage defines the effect, names land-surface modification as its main cause with waste heat secondary, and gives the scale of urban land. The other choices misstate one of those details.', '{"A": "The text calls waste heat a secondary contributor, not the main cause.", "D": "The text says the difference is usually larger at night than during the day.", "C": "The text gives 0.5% of Earth''s land surface, not half."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF005', 'HDSAT-RW-M16-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "a windy night."}, {"id": "B", "text": "a calm afternoon."}, {"id": "C", "text": "a windy afternoon."}, {"id": "D", "text": "a calm night."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF005', 'D', ARRAY['D']::TEXT[], 'The text says the urban-rural difference is larger at night and most apparent when winds are weak, so a calm night combines both conditions.', '{"C": "Wind weakens the effect, and daytime differences are usually smaller.", "A": "Weak winds favor the effect, but the text says the difference is usually larger at night.", "B": "Calm conditions favor the effect, but the daytime difference is usually smaller."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS005', 'HDSAT-RW-M16-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces the history of research on urban temperatures from the nineteenth century onward."}, {"id": "B", "text": "It compares several cities and ranks them by the strength of their heat islands."}, {"id": "C", "text": "It defines the effect, identifies its causes, notes the scale of urban land, and clarifies the term."}, {"id": "D", "text": "It describes the effect and then proposes engineering solutions to reduce it."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS005', 'C', ARRAY['C']::TEXT[], 'The text moves from a definition to causes, then to the small share of land cities occupy, and ends by explaining how the term heat island is used.', '{"B": "No individual cities are compared or ranked.", "D": "No solutions are proposed in this passage.", "A": "No historical account of the research is given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE005', 'HDSAT-RW-M16-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas.', 'Which quotation from the text most directly supports the claim that the urban heat island affects conditions beyond temperature itself?', '[{"id": "A", "text": "Increases in heat within urban centers increase the length of growing seasons, decrease air quality by increasing the production of pollutants such as ozone, and decrease water quality as warmer waters flow into area streams and put stress on their ecosystems."}, {"id": "B", "text": "Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population."}, {"id": "C", "text": "The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak"}, {"id": "D", "text": "The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE005', 'A', ARRAY['A']::TEXT[], 'Only the quotation lists consequences for growing seasons, air quality and water quality, which are effects beyond temperature.', '{"C": "This sentence describes when the temperature difference is strongest, not its wider effects.", "B": "This sentence gives the scale of urban land and population.", "D": "This sentence identifies the causes of the effect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI006', 'HDSAT-RW-M16-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Svalbard Global Seed Vault (Norwegian: Svalbard globale frøhvelv) is a secure backup facility for the Earth''s crop diversity on the Norwegian island of Spitsbergen in the remote Arctic Svalbard archipelago. The Seed Vault provides long-term storage for duplicates of seeds from around the world, conserved in gene banks. The Seed Vault is managed under terms spelled out in a tripartite agreement among the Norwegian government, the Crop Trust, and the Nordic Genetic Resource Center (NordGen). The Norwegian government entirely funded the Seed Vault''s approximately 45 million kr (US$8.8 million in 2008) construction cost. Norway and the Crop Trust pay for operational costs. Storing seeds in the vault is free to depositors.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Seed Vault is a working gene bank that lends seeds to farmers around the world."}, {"id": "B", "text": "The Seed Vault was built and is operated entirely by the Crop Trust."}, {"id": "C", "text": "Storing seeds in the vault costs depositors about 45 million kr."}, {"id": "D", "text": "The Svalbard Global Seed Vault stores backup copies of the world''s crop seeds, and depositors pay nothing to use it."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Svalbard Global Seed Vault", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Svalbard_Global_Seed_Vault', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI006', 'D', ARRAY['D']::TEXT[], 'The text presents the vault as a secure backup for crop diversity, describes the tripartite management and funding, and states that storage is free to depositors.', '{"A": "The text describes the vault as a backup that stores duplicates, not as a lending collection.", "B": "Construction was funded by the Norwegian government, and Norway and the Crop Trust share operating costs.", "C": "The 45 million kr figure is the construction cost, and storage is free to depositors."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF006', 'HDSAT-RW-M16-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Svalbard Global Seed Vault (Norwegian: Svalbard globale frøhvelv) is a secure backup facility for the Earth''s crop diversity on the Norwegian island of Spitsbergen in the remote Arctic Svalbard archipelago. The Seed Vault provides long-term storage for duplicates of seeds from around the world, conserved in gene banks. The Seed Vault is managed under terms spelled out in a tripartite agreement among the Norwegian government, the Crop Trust, and the Nordic Genetic Resource Center (NordGen). The Norwegian government entirely funded the Seed Vault''s approximately 45 million kr (US$8.8 million in 2008) construction cost. Norway and the Crop Trust pay for operational costs. Storing seeds in the vault is free to depositors.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "let gene banks preserve backup copies without adding storage costs."}, {"id": "B", "text": "earn revenue by charging depositors for storage."}, {"id": "C", "text": "limit deposits to seeds produced in Norway."}, {"id": "D", "text": "replace the gene banks that hold the original seeds."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Svalbard Global Seed Vault", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Svalbard_Global_Seed_Vault', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF006', 'A', ARRAY['A']::TEXT[], 'Because storage is free and the vault holds duplicates of seeds conserved elsewhere, the arrangement lets gene banks keep backups without paying for additional storage.', '{"B": "The text says storing seeds is free to depositors, so the vault does not earn revenue that way.", "D": "The vault stores duplicates of seeds conserved in gene banks, which implies the gene banks continue to hold the originals.", "C": "No national restriction on deposits is described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS006', 'HDSAT-RW-M16-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The Svalbard Global Seed Vault (Norwegian: Svalbard globale frøhvelv) is a secure backup facility for the Earth''s crop diversity on the Norwegian island of Spitsbergen in the remote Arctic Svalbard archipelago. The Seed Vault provides long-term storage for duplicates of seeds from around the world, conserved in gene banks. The Seed Vault is managed under terms spelled out in a tripartite agreement among the Norwegian government, the Crop Trust, and the Nordic Genetic Resource Center (NordGen). The Norwegian government entirely funded the Seed Vault''s approximately 45 million kr (US$8.8 million in 2008) construction cost. Norway and the Crop Trust pay for operational costs. Storing seeds in the vault is free to depositors.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the construction of the vault in technical detail and evaluates its engineering."}, {"id": "B", "text": "It identifies a facility and its location, explains its purpose, and describes how it is managed and funded."}, {"id": "C", "text": "It compares the vault with other seed banks and argues that one of them is superior."}, {"id": "D", "text": "It recounts the history of crop domestication before introducing the vault."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Svalbard Global Seed Vault", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Svalbard_Global_Seed_Vault', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS006', 'B', ARRAY['B']::TEXT[], 'The passage introduces the vault and its Arctic location, states that it stores duplicate seeds, and then covers management and funding.', '{"A": "The text gives no engineering detail or evaluation.", "C": "No other seed banks are compared or ranked.", "D": "The history of crop domestication is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE006', 'HDSAT-RW-M16-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'The Svalbard Global Seed Vault (Norwegian: Svalbard globale frøhvelv) is a secure backup facility for the Earth''s crop diversity on the Norwegian island of Spitsbergen in the remote Arctic Svalbard archipelago. The Seed Vault provides long-term storage for duplicates of seeds from around the world, conserved in gene banks. The Seed Vault is managed under terms spelled out in a tripartite agreement among the Norwegian government, the Crop Trust, and the Nordic Genetic Resource Center (NordGen). The Norwegian government entirely funded the Seed Vault''s approximately 45 million kr (US$8.8 million in 2008) construction cost. Norway and the Crop Trust pay for operational costs. Storing seeds in the vault is free to depositors.', 'Which quotation from the text most directly supports the claim that the Seed Vault is a safeguard rather than a substitute for existing collections?', '[{"id": "A", "text": "Storing seeds in the vault is free to depositors."}, {"id": "B", "text": "The Seed Vault is managed under terms spelled out in a tripartite agreement among the Norwegian government, the Crop Trust, and the Nordic Genetic Resource Center (NordGen)."}, {"id": "C", "text": "The Seed Vault provides long-term storage for duplicates of seeds from around the world, conserved in gene banks."}, {"id": "D", "text": "The Norwegian government entirely funded the Seed Vault''s approximately 45 million kr (US$8.8 million in 2008) construction cost."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Svalbard Global Seed Vault", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Svalbard_Global_Seed_Vault', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE006', 'C', ARRAY['C']::TEXT[], 'The word duplicates, together with conserved in gene banks, shows that the vault backs up collections held elsewhere rather than replacing them.', '{"D": "This sentence describes funding, not the vault''s relation to existing collections.", "A": "This sentence describes the cost to depositors.", "B": "This sentence describes management, not the role of the stored seeds."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI007', 'HDSAT-RW-M16-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Antikythera mechanism ( AN-tik-ih-THEER-ə, US also  AN-ty-kih-) is an ancient Greek hand-powered orrery (model of the Solar System) built in the 2nd century BC and discovered in 1901. It is the oldest known example of an analogue computer. It could be used to predict astronomical positions and eclipses decades in advance. It could also be used to track the four-year cycle of athletic games similar to an olympiad, the cycle of the ancient Olympic Games.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Antikythera mechanism is the oldest known example of a geared clock."}, {"id": "B", "text": "The Antikythera mechanism was built in the 2nd century AD to track the modern Olympic Games."}, {"id": "C", "text": "The mechanism was discovered intact and is displayed today as a single fragment."}, {"id": "D", "text": "The Antikythera mechanism is the oldest known analogue computer, built to predict astronomical events and athletic cycles."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antikythera mechanism", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antikythera_mechanism', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI007', 'D', ARRAY['D']::TEXT[], 'The passage identifies the object, dates it, calls it the oldest known analogue computer, and lists what it could predict and track.', '{"B": "The text dates it to the 2nd century BC and compares its athletic cycle to the ancient Olympic Games.", "A": "The text calls it an analogue computer, not a clock.", "C": "It was found as one lump and later separated into fragments, so it was not discovered intact."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF007', 'HDSAT-RW-M16-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The Antikythera mechanism ( AN-tik-ih-THEER-ə, US also  AN-ty-kih-) is an ancient Greek hand-powered orrery (model of the Solar System) built in the 2nd century BC and discovered in 1901. It is the oldest known example of an analogue computer. It could be used to predict astronomical positions and eclipses decades in advance. It could also be used to track the four-year cycle of athletic games similar to an olympiad, the cycle of the ancient Olympic Games.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "replace written calendars throughout the Greek world."}, {"id": "B", "text": "measure the weight of cargo carried by Greek ships."}, {"id": "C", "text": "record the positions of the stars at one particular moment."}, {"id": "D", "text": "model recurring cycles rather than perform a single calculation."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antikythera mechanism", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antikythera_mechanism', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF007', 'D', ARRAY['D']::TEXT[], 'The mechanism tracked the four-year athletic cycle and predicted astronomical positions decades ahead, both of which are recurring patterns rather than one-off calculations.', '{"B": "The text describes astronomical and athletic cycles, not cargo weight.", "A": "Nothing in the text says the device replaced calendars.", "C": "A device that predicts decades in advance is not limited to one moment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS007', 'HDSAT-RW-M16-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The Antikythera mechanism ( AN-tik-ih-THEER-ə, US also  AN-ty-kih-) is an ancient Greek hand-powered orrery (model of the Solar System) built in the 2nd century BC and discovered in 1901. It is the oldest known example of an analogue computer. It could be used to predict astronomical positions and eclipses decades in advance. It could also be used to track the four-year cycle of athletic games similar to an olympiad, the cycle of the ancient Olympic Games.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It identifies the object and its date, then describes what the object could do."}, {"id": "B", "text": "It describes the shipwreck in detail and explains how the wreck was located."}, {"id": "C", "text": "It compares the mechanism with modern computers and ranks their accuracy."}, {"id": "D", "text": "It presents a debate about the mechanism''s age and settles it with new evidence."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antikythera mechanism", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antikythera_mechanism', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS007', 'A', ARRAY['A']::TEXT[], 'The passage introduces the mechanism and its date, names it the oldest known analogue computer, and lists its predictive functions.', '{"B": "The shipwreck is mentioned only as the place of discovery, without detail.", "C": "Modern computers are not discussed.", "D": "No debate about the age is presented."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE007', 'HDSAT-RW-M16-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Antikythera mechanism ( AN-tik-ih-THEER-ə, US also  AN-ty-kih-) is an ancient Greek hand-powered orrery (model of the Solar System) built in the 2nd century BC and discovered in 1901. It is the oldest known example of an analogue computer. It could be used to predict astronomical positions and eclipses decades in advance. It could also be used to track the four-year cycle of athletic games similar to an olympiad, the cycle of the ancient Olympic Games.', 'Which quotation from the text most directly supports the claim that the Antikythera mechanism was a predictive instrument?', '[{"id": "A", "text": "It could also be used to track the four-year cycle of athletic games similar to an olympiad"}, {"id": "B", "text": "It is the oldest known example of an analogue computer."}, {"id": "C", "text": "built in the 2nd century BC and discovered in 1901"}, {"id": "D", "text": "It could be used to predict astronomical positions and eclipses decades in advance."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antikythera mechanism", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antikythera_mechanism', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE007', 'D', ARRAY['D']::TEXT[], 'The quotation explicitly names prediction of astronomical positions and eclipses, which is the claim being supported.', '{"B": "This sentence ranks the device among computers but does not say what it predicted.", "C": "This fragment gives its date and discovery.", "A": "Tracking a cycle is a function, but this quotation does not mention prediction."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI008', 'HDSAT-RW-M16-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A mycorrhizal network (also known as a common mycorrhizal network or CMN) is an underground network found in forests and other plant communities, created by the hyphae of mycorrhizal fungi joining with plant roots. This network connects individual plants together. Mycorrhizal relationships are most commonly mutualistic, with both partners benefiting, but can be commensal or parasitic, and a single partnership may change between any of the three types of symbiosis at different times. Mycorrhizal networks were discovered in 1997 by Suzanne Simard, professor of forest ecology at the University of British Columbia in Canada. Simard grew up in Canadian forests where her family had made a living as foresters for generations. Her field studies revealed that trees are linked to neighboring trees by an underground network of fungi that resembles the neural networks in the brain. In one study, Simard watched as a Douglas fir that had been injured by insects appeared to send chemical warning signals to a ponderosa pine growing nearby. The pine tree then produced defense enzymes to protect against the insect.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All mycorrhizal relationships benefit both partners equally."}, {"id": "B", "text": "The networks are made of tree roots that fuse together underground."}, {"id": "C", "text": "Mycorrhizal networks link plants underground and can carry warning signals between neighboring trees."}, {"id": "D", "text": "Suzanne Simard discovered the networks while working as a forester."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycorrhizal network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycorrhizal_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI008', 'C', ARRAY['C']::TEXT[], 'The passage defines the network, explains that relationships vary, and describes Simard''s study in which an injured fir appeared to warn a nearby pine, which then produced defense enzymes.', '{"A": "The text says relationships can be mutualistic, commensal or parasitic, and can change over time.", "B": "The networks are created by fungal hyphae joining plant roots, not by roots fusing.", "D": "Simard is described as a professor whose family were foresters; the text does not say she worked as one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF008', 'HDSAT-RW-M16-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A mycorrhizal network (also known as a common mycorrhizal network or CMN) is an underground network found in forests and other plant communities, created by the hyphae of mycorrhizal fungi joining with plant roots. This network connects individual plants together. Mycorrhizal relationships are most commonly mutualistic, with both partners benefiting, but can be commensal or parasitic, and a single partnership may change between any of the three types of symbiosis at different times. Mycorrhizal networks were discovered in 1997 by Suzanne Simard, professor of forest ecology at the University of British Columbia in Canada. Simard grew up in Canadian forests where her family had made a living as foresters for generations. Her field studies revealed that trees are linked to neighboring trees by an underground network of fungi that resembles the neural networks in the brain. In one study, Simard watched as a Douglas fir that had been injured by insects appeared to send chemical warning signals to a ponderosa pine growing nearby. The pine tree then produced defense enzymes to protect against the insect.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "a tree can produce a chemical defense after a neighboring tree is damaged."}, {"id": "B", "text": "insects prefer ponderosa pines to Douglas firs."}, {"id": "C", "text": "injured trees stop sending signals to their neighbors."}, {"id": "D", "text": "the fungi produce the defense enzymes themselves."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycorrhizal network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycorrhizal_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF008', 'A', ARRAY['A']::TEXT[], 'The pine produced defense enzymes after the fir was injured and appeared to send warning signals, which supports the inference that damage to one tree can trigger a chemical defense in another.', '{"B": "The study does not compare insect preference between the two species.", "D": "The text says the pine produced the enzymes, not the fungi.", "C": "The injured fir appeared to send signals, which is the opposite of stopping."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS008', 'HDSAT-RW-M16-TS008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A mycorrhizal network (also known as a common mycorrhizal network or CMN) is an underground network found in forests and other plant communities, created by the hyphae of mycorrhizal fungi joining with plant roots. This network connects individual plants together. Mycorrhizal relationships are most commonly mutualistic, with both partners benefiting, but can be commensal or parasitic, and a single partnership may change between any of the three types of symbiosis at different times. Mycorrhizal networks were discovered in 1997 by Suzanne Simard, professor of forest ecology at the University of British Columbia in Canada. Simard grew up in Canadian forests where her family had made a living as foresters for generations. Her field studies revealed that trees are linked to neighboring trees by an underground network of fungi that resembles the neural networks in the brain. In one study, Simard watched as a Douglas fir that had been injured by insects appeared to send chemical warning signals to a ponderosa pine growing nearby. The pine tree then produced defense enzymes to protect against the insect.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two competing definitions of a scientific term and rejects one of them."}, {"id": "B", "text": "It argues that foresters should plant only Douglas fir and ponderosa pine together."}, {"id": "C", "text": "It describes the life cycle of mycorrhizal fungi from spore to mature hypha."}, {"id": "D", "text": "It defines a network, explains the types of relationships involved, and describes a study of signaling between trees."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycorrhizal network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycorrhizal_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS008', 'D', ARRAY['D']::TEXT[], 'The text defines the network, describes the range of symbiotic relationships, and then presents Simard''s field study of signaling between a fir and a pine.', '{"A": "Only one definition is given, and neither of two definitions is rejected.", "C": "The fungal life cycle is not described.", "B": "No planting recommendation is made."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE008', 'HDSAT-RW-M16-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A mycorrhizal network (also known as a common mycorrhizal network or CMN) is an underground network found in forests and other plant communities, created by the hyphae of mycorrhizal fungi joining with plant roots. This network connects individual plants together. Mycorrhizal relationships are most commonly mutualistic, with both partners benefiting, but can be commensal or parasitic, and a single partnership may change between any of the three types of symbiosis at different times. Mycorrhizal networks were discovered in 1997 by Suzanne Simard, professor of forest ecology at the University of British Columbia in Canada. Simard grew up in Canadian forests where her family had made a living as foresters for generations. Her field studies revealed that trees are linked to neighboring trees by an underground network of fungi that resembles the neural networks in the brain. In one study, Simard watched as a Douglas fir that had been injured by insects appeared to send chemical warning signals to a ponderosa pine growing nearby. The pine tree then produced defense enzymes to protect against the insect.', 'Which quotation from the text most directly supports the claim that trees in a mycorrhizal network can respond to damage suffered by a neighbor?', '[{"id": "A", "text": "Mycorrhizal networks were discovered in 1997 by Suzanne Simard, professor of forest ecology at the University of British Columbia in Canada."}, {"id": "B", "text": "In one study, Simard watched as a Douglas fir that had been injured by insects appeared to send chemical warning signals to a ponderosa pine growing nearby. The pine tree then produced defense enzymes to protect against the insect."}, {"id": "C", "text": "Mycorrhizal relationships are most commonly mutualistic, with both partners benefiting"}, {"id": "D", "text": "A mycorrhizal network (also known as a common mycorrhizal network or CMN) is an underground network found in forests and other plant communities"}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycorrhizal network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycorrhizal_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE008', 'B', ARRAY['B']::TEXT[], 'Only the quotation describes injury, a warning signal and a defensive response in the neighboring tree.', '{"C": "This sentence describes the general type of relationship, not a response to damage.", "A": "This sentence credits the discovery.", "D": "This sentence defines the network and where it is found."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI009', 'HDSAT-RW-M16-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Coral bleaching is the process where corals become white due to loss of symbiotic algae and photosynthetic pigments. This loss of pigment can be caused by various stressors, such as changes in water temperature, light, salinity, or nutrients. A bleached coral is under stress, more vulnerable to starvation and disease, and at risk of death. The leading cause of coral bleaching is rising ocean temperatures due to climate change. Take up of carbon dioxide from the atmosphere also has been acidifying the oceans and affects coral health. Large-scale bleaching events can devastate entire reef ecosystems, affecting biodiversity and the livelihoods of coastal communities that depend on healthy reefs for food, tourism, and protection from storm surges.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Coral bleaching is caused primarily by pollution from coastal communities."}, {"id": "B", "text": "Coral bleaching increases the biodiversity of reef ecosystems."}, {"id": "C", "text": "Bleached corals are already dead and cannot recover."}, {"id": "D", "text": "Coral bleaching, driven mainly by warming oceans, threatens reefs and the communities that depend on them."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral bleaching", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_bleaching', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI009', 'D', ARRAY['D']::TEXT[], 'The passage defines bleaching, lists its causes with rising ocean temperatures as the leading one, describes the stress it places on corals, and notes the consequences for reefs and coastal communities.', '{"A": "The text names rising ocean temperatures as the leading cause and does not identify coastal pollution as the cause.", "C": "The text says a bleached coral is under stress and at risk of death, not that it is already dead.", "B": "The text says large-scale bleaching can devastate reef ecosystems and affect biodiversity, not increase it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF009', 'HDSAT-RW-M16-INF009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Coral bleaching is the process where corals become white due to loss of symbiotic algae and photosynthetic pigments. This loss of pigment can be caused by various stressors, such as changes in water temperature, light, salinity, or nutrients. A bleached coral is under stress, more vulnerable to starvation and disease, and at risk of death. The leading cause of coral bleaching is rising ocean temperatures due to climate change. Take up of carbon dioxide from the atmosphere also has been acidifying the oceans and affects coral health. Large-scale bleaching events can devastate entire reef ecosystems, affecting biodiversity and the livelihoods of coastal communities that depend on healthy reefs for food, tourism, and protection from storm surges.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "storm surges become more frequent when reefs are healthy."}, {"id": "B", "text": "coral bleaching raises the salinity of coastal waters."}, {"id": "C", "text": "reefs that support coastal fisheries may deteriorate when corals bleach."}, {"id": "D", "text": "bleached corals attract more fish than healthy corals do."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral bleaching", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_bleaching', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF009', 'C', ARRAY['C']::TEXT[], 'The text says coastal communities depend on healthy reefs for food, and that bleaching can devastate reef ecosystems, which supports the inference that fisheries depending on those reefs may suffer.', '{"D": "The text links bleaching to vulnerability and death, not to attracting fish.", "A": "Healthy reefs are described as protection from storm surges, not as a cause of them.", "B": "Salinity is listed as a possible stressor, not as a result of bleaching."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS009', 'HDSAT-RW-M16-TS009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Coral bleaching is the process where corals become white due to loss of symbiotic algae and photosynthetic pigments. This loss of pigment can be caused by various stressors, such as changes in water temperature, light, salinity, or nutrients. A bleached coral is under stress, more vulnerable to starvation and disease, and at risk of death. The leading cause of coral bleaching is rising ocean temperatures due to climate change. Take up of carbon dioxide from the atmosphere also has been acidifying the oceans and affects coral health. Large-scale bleaching events can devastate entire reef ecosystems, affecting biodiversity and the livelihoods of coastal communities that depend on healthy reefs for food, tourism, and protection from storm surges.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a solution to bleaching and evaluates how well the solution works."}, {"id": "B", "text": "It defines bleaching, lists its causes, and describes its effects on corals and coastal communities."}, {"id": "C", "text": "It compares bleaching in the Atlantic and Pacific oceans."}, {"id": "D", "text": "It traces the discovery of coral bleaching through the work of a single researcher."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral bleaching", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_bleaching', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS009', 'B', ARRAY['B']::TEXT[], 'The passage defines the process, names stressors and the leading cause, and then moves to consequences for corals, reefs and people.', '{"A": "No solution is proposed or evaluated.", "C": "No comparison between oceans is made.", "D": "No researcher or history of discovery is mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE009', 'HDSAT-RW-M16-CE009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Coral bleaching is the process where corals become white due to loss of symbiotic algae and photosynthetic pigments. This loss of pigment can be caused by various stressors, such as changes in water temperature, light, salinity, or nutrients. A bleached coral is under stress, more vulnerable to starvation and disease, and at risk of death. The leading cause of coral bleaching is rising ocean temperatures due to climate change. Take up of carbon dioxide from the atmosphere also has been acidifying the oceans and affects coral health. Large-scale bleaching events can devastate entire reef ecosystems, affecting biodiversity and the livelihoods of coastal communities that depend on healthy reefs for food, tourism, and protection from storm surges.', 'Which quotation from the text most directly supports the claim that coral bleaching has economic consequences for people?', '[{"id": "A", "text": "This loss of pigment can be caused by various stressors, such as changes in water temperature, light, salinity, or nutrients."}, {"id": "B", "text": "Large-scale bleaching events can devastate entire reef ecosystems, affecting biodiversity and the livelihoods of coastal communities that depend on healthy reefs for food, tourism, and protection from storm surges."}, {"id": "C", "text": "A bleached coral is under stress, more vulnerable to starvation and disease, and at risk of death."}, {"id": "D", "text": "The leading cause of coral bleaching is rising ocean temperatures due to climate change."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral bleaching", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_bleaching', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE009', 'B', ARRAY['B']::TEXT[], 'Only the quotation mentions livelihoods, food and tourism, which are the economic consequences the claim concerns.', '{"D": "This sentence identifies the leading cause, not an economic effect.", "C": "This sentence describes the condition of a bleached coral.", "A": "This sentence lists stressors that can cause bleaching."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
