INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI010', 'D', ARRAY['D']::TEXT[], 'The passage describes the records, their contents and intended audience, and calls them a time capsule; it also notes the enormous timescale of the journey.', '{"A": "The text says neither spacecraft is heading toward a particular star.", "B": "The records contain sounds and data for reconstructing images.", "C": "The records are identical, and one copy is aboard each of the two spacecraft."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
