INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF010', 'A', ARRAY['A']::TEXT[], 'The text places the nearest stellar approach about 40,000 years away, which supports the inference that the records are unlikely to be found and interpreted in the near future.', '{"D": "The text does not question whether the records will survive.", "C": "The text states that Voyager 1 will pass near Gliese 445, so this is not a matter of likelihood.", "B": "The text states that the records do contain such information."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
