INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS010', 'D', ARRAY['D']::TEXT[], 'The first paragraph covers the records, their contents and purpose; the second covers the spacecraft''s path and the 40,000-year timescale.', '{"C": "No engineering detail or instrument comparison is given.", "B": "No argument about the records'' contents is made.", "A": "No discovery is described; the records are intended for a possible future finder."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
