INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE010', 'A', ARRAY['A']::TEXT[], 'The quotation explicitly says the selected sounds and images portray the diversity of life and culture on Earth.', '{"D": "This sentence describes the number of records and their placement.", "B": "This sentence characterizes the records but does not mention diversity.", "C": "This sentence describes the spacecraft''s path."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI011', 'HDSAT-RW-M16-CI011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Standard time is the synchronisation of clocks within a geographical region to a single time standard, rather than different localities in the region using their own local mean time. The term is also used to contrast with daylight saving time, a period of the year when clocks are shifted ahead one hour, supposedly to make better use of daily sunlight from spring to fall. Applied globally in the 20th century, the geographical regions became time zones. The standard time in each time zone has come to be defined as an offset from Universal Time. A further offset is applied for part of the year in regions with daylight saving time. Generally, standard time agrees with the local mean time at some meridian that passes through the region, often near the centre of the region. Historically, standard time was established during the 19th century to aid weather forecasting and train travel.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Standard time synchronizes clocks across a region and was adopted to support weather forecasting and rail travel."}, {"id": "B", "text": "Time zones were established in the 19th century and later replaced by Universal Time."}, {"id": "C", "text": "Standard time was introduced in order to make daylight saving time possible."}, {"id": "D", "text": "Standard time requires each locality to keep its own local mean time."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standard time", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standard_time', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI011', 'A', ARRAY['A']::TEXT[], 'The passage defines standard time as regional synchronization, distinguishes it from daylight saving time, explains its relation to Universal Time, and gives its historical purpose.', '{"C": "The text contrasts standard time with daylight saving time rather than presenting it as a prerequisite.", "D": "The text defines standard time as a single standard for a region rather than separate local times.", "B": "The text says time zones were applied globally in the 20th century and defined as offsets from Universal Time, not replaced by it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-INF011', 'HDSAT-RW-M16-INF011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Standard time is the synchronisation of clocks within a geographical region to a single time standard, rather than different localities in the region using their own local mean time. The term is also used to contrast with daylight saving time, a period of the year when clocks are shifted ahead one hour, supposedly to make better use of daily sunlight from spring to fall. Applied globally in the 20th century, the geographical regions became time zones. The standard time in each time zone has come to be defined as an offset from Universal Time. A further offset is applied for part of the year in regions with daylight saving time. Generally, standard time agrees with the local mean time at some meridian that passes through the region, often near the centre of the region. Historically, standard time was established during the 19th century to aid weather forecasting and train travel.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "every region already used Universal Time."}, {"id": "B", "text": "trains crossing a region might have kept clocks that disagreed with one another."}, {"id": "C", "text": "rail travel was unaffected by local time."}, {"id": "D", "text": "weather forecasting was impossible."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standard time", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standard_time', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF011', 'B', ARRAY['B']::TEXT[], 'Before standard time, localities used their own local mean time. The text says standard time was established to aid train travel, which supports the inference that differing local clocks caused problems for railways.', '{"D": "The text says standard time aided forecasting, not that forecasting was impossible without it.", "C": "The text presents train travel as a reason for adopting standard time, which implies local time did affect it.", "A": "Universal Time is described as the reference for modern time zones, not as a pre-existing standard everywhere."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-TS011', 'HDSAT-RW-M16-TS011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Standard time is the synchronisation of clocks within a geographical region to a single time standard, rather than different localities in the region using their own local mean time. The term is also used to contrast with daylight saving time, a period of the year when clocks are shifted ahead one hour, supposedly to make better use of daily sunlight from spring to fall. Applied globally in the 20th century, the geographical regions became time zones. The standard time in each time zone has come to be defined as an offset from Universal Time. A further offset is applied for part of the year in regions with daylight saving time. Generally, standard time agrees with the local mean time at some meridian that passes through the region, often near the centre of the region. Historically, standard time was established during the 19th century to aid weather forecasting and train travel.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates the invention of the mechanical clock and its spread through Europe."}, {"id": "B", "text": "It compares the accuracy of several timekeeping devices and ranks them."}, {"id": "C", "text": "It defines standard time, contrasts it with daylight saving time, explains how time zones relate to Universal Time, and gives a historical reason for its adoption."}, {"id": "D", "text": "It argues that daylight saving time should be abolished."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standard time", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standard_time', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-TS011', 'C', ARRAY['C']::TEXT[], 'The text proceeds from definition to contrast to the modern offset system and ends with the nineteenth-century reasons for adopting standard time.', '{"A": "No history of the mechanical clock is given.", "B": "No timekeeping devices are compared or ranked.", "D": "Daylight saving time is explained, not criticized."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CE011', 'HDSAT-RW-M16-CE011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Standard time is the synchronisation of clocks within a geographical region to a single time standard, rather than different localities in the region using their own local mean time. The term is also used to contrast with daylight saving time, a period of the year when clocks are shifted ahead one hour, supposedly to make better use of daily sunlight from spring to fall. Applied globally in the 20th century, the geographical regions became time zones. The standard time in each time zone has come to be defined as an offset from Universal Time. A further offset is applied for part of the year in regions with daylight saving time. Generally, standard time agrees with the local mean time at some meridian that passes through the region, often near the centre of the region. Historically, standard time was established during the 19th century to aid weather forecasting and train travel.', 'Which quotation from the text most directly supports the claim that practical coordination, rather than astronomy alone, drove the adoption of standard time?', '[{"id": "A", "text": "Generally, standard time agrees with the local mean time at some meridian that passes through the region, often near the centre of the region."}, {"id": "B", "text": "The standard time in each time zone has come to be defined as an offset from Universal Time."}, {"id": "C", "text": "The term is also used to contrast with daylight saving time, a period of the year when clocks are shifted ahead one hour"}, {"id": "D", "text": "Historically, standard time was established during the 19th century to aid weather forecasting and train travel."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Standard time", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Standard_time', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CE011', 'D', ARRAY['D']::TEXT[], 'The quotation names weather forecasting and train travel as the purposes behind standard time, which are practical coordination needs rather than astronomical ones.', '{"A": "This sentence describes the astronomical basis of standard time, not the reason it was adopted.", "B": "This sentence describes how time zones are defined today.", "C": "This sentence distinguishes standard time from daylight saving time."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M16-CI012', 'HDSAT-RW-M16-CI012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A peatland is a type of wetland whose soils consist of organic matter from decaying plants, forming layers of peat. Peatlands arise because of incomplete decomposition of organic matter, usually litter from vegetation, due to water-logging and subsequent anoxia. Peatlands are unusual landforms that derive mostly from biological rather than physical processes, and can take on characteristic shapes and surface patterning.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-CI012', 'B', ARRAY['B']::TEXT[], 'The passage explains that waterlogging and anoxia prevent complete decomposition, describes how peatlands form, and ends by identifying them as the largest natural carbon store on land.', '{"A": "The text attributes peat formation to incomplete decomposition, the opposite of rapid decay.", "D": "The text says peatlands derive mostly from biological rather than physical processes.", "C": "The text calls peatlands the largest natural carbon store on land."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
