INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M16-INF012', 'D', ARRAY['D']::TEXT[], 'Peat accumulates because waterlogging and anoxia inhibit decomposition. Draining removes that inhibition, so the stored organic matter would break down faster.', '{"A": "Waterlogging is what slows decomposition, so removing it would work against further peat formation.", "B": "The text ties carbon storage to waterlogged, oxygen-poor conditions, so changing those conditions would affect the stored carbon.", "C": "A mire is a peatland that is actively forming peat, which draining would not promote."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
